style.css:
@-moz-document domain("youtube.com"), domain("m.youtube.com"), regexp("^https?://(www|m)\.youtube\.(com|be)/.*") {
:root {
    /* Accurate Sweet KDE palette – deep dark with purple/mauve/lavender */
    --bg-main: #0d1117;           /* Deep dark base, close to Sweet's background */
    --bg-secondary: #161b22;      /* Panels, sidebars, cards – subtle elevation */
    --bg-tertiary: #1f2937;       /* Hover/active states, elevated surfaces */
    --text-primary: #e2e8f0;      /* Main readable text – light gray with lavender tint */
    --text-secondary: #a0aec0;    /* Muted text: descriptions, timestamps */
    --accent: #c084fc;            /* Core Sweet purple/mauve accent */
    --accent-light: #d8b4fe;      /* Hover / lighter variant */
    --accent-dark: #a855f7;       /* Active / pressed */
    --glow: 0 0 12px rgba(192, 132, 252, 0.3); /* Soft purple glow for hovers */
    --border-subtle: rgba(192, 132, 252, 0.12);
  }

  /* Core app background & text */
  ytd-app, body, html {
    background: var(--bg-main) !important;
    color: var(--text-primary) !important;
  }

  /* Header / masthead – semi-transparent feel */
  #container.ytd-masthead,
  ytd-masthead {
    background: var(--bg-secondary) !important;
    border-bottom: 1px solid var(--border-subtle) !important;
    backdrop-filter: blur(6px) !important; /* KDE blur emulation */
  }

  /* Search bar – rounded, Sweet style */
  #search.ytd-searchbox,
  .ytd-searchbox {
    background: var(--bg-tertiary) !important;
    border: 1px solid var(--border-subtle) !important;
    border-radius: 999px !important;
  }
  #search-icon-legacy.ytd-searchbox,
  #voice-search-button.ytd-searchbox {
    color: var(--accent) !important;
  }

  /* Video player & progress – accent on progress */
  .html5-video-player {
    background: #000 !important;
  }
  .ytp-progress-bar {
    --ytp-progress-color: var(--accent) !important;
    --ytp-loaded-color: rgba(192, 132, 252, 0.35) !important;
  }
  .ytp-chrome-bottom {
    background: rgba(22, 27, 34, 0.88) !important; /* semi-trans like KDE panels */
    backdrop-filter: blur(10px) !important;
  }
  .ytp-button:hover {
    background: rgba(192, 132, 252, 0.18) !important;
  }

  /* Thumbnails & cards – rounded + glow hover (Sweet interactive feel) */
  ytd-rich-item-renderer,
  ytd-compact-video-renderer,
  ytd-grid-video-renderer,
  ytd-thumbnail-overlay-resume-playback-renderer {
    border-radius: 12px !important;
    overflow: hidden;
    background: var(--bg-secondary) !important;
    transition: transform 0.25s ease, box-shadow 0.25s ease !important;
  }
  ytd-rich-item-renderer:hover,
  ytd-compact-video-renderer:hover,
  ytd-grid-video-renderer:hover {
    transform: translateY(-6px) !important;
    box-shadow: var(--glow) !important;
    border: 1px solid var(--border-subtle) !important;
  }

  /* Titles, metadata, channel names */
  #video-title,
  yt-formatted-string.ytd-video-renderer,
  .ytd-video-meta-block,
  .ytd-channel-name {
    color: var(--text-primary) !important;
  }
  .ytd-badge-supported-renderer,
  #metadata-line.ytd-video-meta-block span {
    color: var(--text-secondary) !important;
  }

  /* Sidebar, related, comments panel */
  #secondary.ytd-watch-flexy,
  ytd-watch-metadata,
  #comments.ytd-watch-flexy {
    background: var(--bg-secondary) !important;
  }

  /* Buttons: subscribe, like, share – Sweet pill style */
  yt-button-renderer button,
  .yt-spec-button-shape-next--filled,
  .ytd-subscribe-button-renderer {
    background: rgba(192, 132, 252, 0.22) !important;
    color: var(--accent) !important;
    border-radius: 999px !important;
    border: none !important;
  }
  yt-button-renderer button:hover,
  .yt-spec-button-shape-next--filled:hover {
    background: rgba(192, 132, 252, 0.38) !important;
  }

  /* Links & highlights */
  a.yt-simple-endpoint,
  .yt-simple-endpoint {
    color: var(--accent) !important;
  }
  a.yt-simple-endpoint:hover {
    color: var(--accent-light) !important;
  }

  /* Optional cleanups (uncomment if you want) */
  /* ytd-reel-shelf-renderer { display: none !important; } */ /* Hide Shorts */
  /* .ytd-promoted-video-renderer { display: none !important; } */ /* Hide ads where possible */

  /* Force dark mode consistency */
  [dark] {
    --yt-spec-base-background: var(--bg-main) !important;
    --yt-spec-raised-background: var(--bg-secondary) !important;
    --yt-spec-inverted-background: var(--bg-tertiary) !important;
  }
}
